      "type": "claim",
      "quote": "The German Section is active in national and international bodies that deal with language policy, for example the Rat für deutsche Rechtschreibung.",
      "gist": "German Section participates in national and international language policy bodies."
    },
    {
      "type": "obligation",
      "quote": "It contributes the Federal Administration’s position and represents the interests of Switzerland.",
      "gist": "German Section contributes Federal Administration's position and represents Switzerland's interests."
    },
    {
      "type": "entity",
      "quote": "Rat für deutsche Rechtschreibung",
      "gist": "Rat für deutsche Rechtschreibung (Council for German Orthography)"
    }
